import { Script, Vector3 } from "@pinefall/sdk";
// Attach alongside the built-in character controller; hold E for a forward dash.
export const defaults = { dashSpeed: 9 };
export default class Boost extends Script {
  fixedUpdate(dt: number) {
    if (!this.ctx.input.has("KeyE")) return;
    const direction = new Vector3(
      -Math.sin(this.ctx.engine.look.yaw),
      0,
      -Math.cos(this.ctx.engine.look.yaw),
    );
    const body = this.ctx.body();
    if (!body) return;
    // Extend the controller's already scheduled displacement, preserving wall collisions.
    const current = body.translation(),
      next = body.nextTranslation();
    this.ctx.engine.physics.move(this.ctx.entity.id, {
      x: next.x - current.x + direction.x * Number(this.ctx.props.dashSpeed) * dt,
      y: next.y - current.y,
      z: next.z - current.z + direction.z * Number(this.ctx.props.dashSpeed) * dt,
    });
  }
}

import { Script } from "@pinefall/sdk";
import type { Entity } from "@pinefall/sdk";
export const defaults = { height: 3 };
export default class BouncePad extends Script {
  trigger(other: Entity, started: boolean) {
    if (!started || other.tag !== "player") return;
    const target = this.ctx.objectFor(other.id);
    if (!target) return;
    this.ctx.teleport(
      [target.position.x, target.position.y + Number(this.ctx.props.height), target.position.z],
      other.id,
    );
    this.ctx.emit("bounce", { player: other.id });
  }
}

import { Script, entity } from "@pinefall/sdk";
export const defaults = { interval: 2, maxCrates: 8 };
export default class Spawner extends Script {
  private next = 0;
  private spawned: string[] = [];
  fixedUpdate() {
    if (this.ctx.time.elapsed < this.next) return;
    this.next = this.ctx.time.elapsed + Math.max(0.2, Number(this.ctx.props.interval));
    const p = this.ctx.object.position;
    const box = entity("Scripted crate", "box", [p.x, p.y + 4, p.z]);
    box.physics = {
      type: "dynamic",
      shape: "box",
      mass: 1,
      friction: 0.6,
      restitution: 0.3,
      sensor: false,
    };
    this.spawned.push(this.ctx.spawn(box).id);
    if (this.spawned.length > Math.max(1, Number(this.ctx.props.maxCrates)))
      this.ctx.destroy(this.spawned.shift()!);
  }
}
